css:
* {
            box-sizing: border-box;
        }

        .apparatus-container {
            position: relative;
            min-height: 600px;
            background: linear-gradient(180deg, #e8f4f8 0%, #d1e8f0 50%, #c4dce6 100%);
            border-radius: 12px;
            box-shadow: 
                inset 0 2px 20px rgba(255,255,255,0.8),
                inset 0 -5px 20px rgba(0,0,0,0.05),
                0 10px 40px rgba(0,0,0,0.1);
            overflow: hidden;
        }

        /* Lab bench surface */
        .apparatus-container::before {
            content: '';
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
            height: 80px;
            background: linear-gradient(180deg, #8b7355 0%, #6b5344 100%);
            box-shadow: inset 0 2px 10px rgba(0,0,0,0.3);
            border-radius: 0 0 12px 12px;
            z-index: 0;
        }

        .glassware {
            position: absolute;
            transition: all 0.6s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .glassware.moving {
            z-index: 100;
        }

        .cleaning-animation {
            animation: clean 1s ease-in-out;
        }

        .filling-animation {
            animation: fill 2s ease-in-out;
        }

        @keyframes clean {
            0% { filter: brightness(1); }
            25% { filter: brightness(1.3); }
            75% { filter: brightness(1.3); }
            100% { filter: brightness(1); }
        }

        @keyframes fill {
            0% { height: 0%; }
            100% { height: 100%; }
        }

        /* Drop falling animation */
        @keyframes dropFall {
            0% { transform: translateY(0) scale(1); opacity: 1; }
            60% { transform: translateY(150px) scale(0.9); opacity: 0.9; }
            100% { transform: translateY(250px) scale(0.7); opacity: 0; }
        }

        .falling-drop {
            position: absolute;
            width: 8px;
            height: 12px;
            border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;
            animation: dropFall 0.8s ease-in forwards;
            pointer-events: none;
            z-index: 50;
        }

        /* 3D Burette Stand */
        .burette-stand {
            position: absolute;
            z-index: 1;
        }

        .stand-rod {
            background: linear-gradient(90deg, #4a4a4a 0%, #7a7a7a 30%, #5a5a5a 70%, #3a3a3a 100%);
            border-radius: 3px;
            box-shadow: 2px 0 8px rgba(0,0,0,0.4);
            position: relative;
        }

        .stand-base {
            position: absolute;
            background: linear-gradient(180deg, #5a5a5a 0%, #3a3a3a 100%);
            border-radius: 4px;
            box-shadow: 0 5px 15px rgba(0,0,0,0.4);
        }

        .stand-clamp {
            position: absolute;
            background: linear-gradient(180deg, #6a6a6a 0%, #4a4a4a 100%);
            border-radius: 3px;
            box-shadow: 0 2px 6px rgba(0,0,0,0.3);
        }

        /* Burette */
        .burette {
            position: absolute;
            z-index: 5;
        }

        .burette-body {
            position: absolute;
            width: 100%;
            height: 100%;
            background: linear-gradient(90deg, 
                rgba(200,220,240,0.3) 0%,
                rgba(255,255,255,0.5) 20%,
                rgba(200,220,240,0.2) 50%,
                rgba(180,200,220,0.4) 80%,
                rgba(160,180,200,0.3) 100%
            );
            border-radius: 12px 12px 3px 3px;
            box-shadow: 
                inset -5px 0 15px rgba(255,255,255,0.6),
                inset 5px 0 10px rgba(0,0,0,0.1),
                -2px 0 8px rgba(0,0,0,0.2);
            border: 1px solid rgba(150,180,200,0.5);
            overflow: hidden;
        }

        .burette-body::before {
            content: '';
            position: absolute;
            left: 4px;
            top: 0;
            width: 5px;
            height: 100%;
            background: linear-gradient(180deg, rgba(255,255,255,0.8), rgba(255,255,255,0.4));
            border-radius: 3px;
        }

        .burette-tip {
            position: absolute;
            left: 50%;
            transform: translateX(-50%);
            background: linear-gradient(90deg,
                rgba(180,200,220,0.4) 0%,
                rgba(255,255,255,0.5) 30%,
                rgba(180,200,220,0.3) 70%,
                rgba(160,180,200,0.4) 100%
            );
            border-radius: 0 0 3px 3px;
        }

        .burette-liquid {
            position: absolute;
            bottom: 0;
            left: 2px;
            right: 2px;
            background: transparent;
            height: 100%;
            transition: height 0.3s;
            border-radius: 0 0 2px 2px;
        }

        .meniscus {
            position: absolute;
            left: 2px;
            right: 2px;
            height: 5px;
            background: linear-gradient(180deg, rgba(255,255,255,0.9) 0%, currentColor 30%);
            border-radius: 50% 50% 0 0;
            transition: top 0.3s;
        }

        .reading-scale {
            position: absolute;
            background: linear-gradient(90deg, rgba(255,255,255,0.95), rgba(245,245,245,0.98));
            border-radius: 3px;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            box-shadow: 2px 2px 6px rgba(0,0,0,0.12);
            border: 1px solid rgba(0,0,0,0.1);
        }

        .reading-scale div {
            text-align: center;
            font-weight: 600;
            color: #333;
        }

        /* Pipette */
        .pipette {
            position: absolute;
            z-index: 10;
        }

        .pipette-body {
            position: absolute;
            width: 100%;
            background: linear-gradient(90deg,
                rgba(200,220,240,0.3) 0%,
                rgba(255,255,255,0.6) 25%,
                rgba(200,220,240,0.2) 50%,
                rgba(180,200,220,0.4) 75%,
                rgba(160,180,200,0.3) 100%
            );
            border-radius: 8px 8px 5px 5px;
            box-shadow: inset -3px 0 10px rgba(255,255,255,0.6), -1px 0 5px rgba(0,0,0,0.15);
            border: 1px solid rgba(150,180,200,0.4);
            overflow: hidden;
        }

        .pipette-body::before {
            content: '';
            position: absolute;
            left: 2px;
            top: 3px;
            width: 3px;
            height: 90%;
            background: linear-gradient(180deg, rgba(255,255,255,0.9), rgba(255,255,255,0.5));
            border-radius: 2px;
            z-index: 2;
        }

        .pipette-liquid {
            position: absolute;
            bottom: 0;
            left: 2px;
            right: 2px;
            height: 0%;
            background: transparent;
            border-radius: 0 0 3px 3px;
            transition: height 0.8s ease-out, background 0.3s;
            z-index: 1;
        }

        .pipette-bulb {
            position: absolute;
            left: 50%;
            transform: translateX(-50%);
            background: linear-gradient(90deg,
                rgba(200,220,240,0.3),
                rgba(255,255,255,0.6) 30%,
                rgba(200,220,240,0.2) 50%,
                rgba(180,200,220,0.4) 70%,
                rgba(160,180,200,0.3)
            );
            border-radius: 50%;
            box-shadow: inset -5px 0 12px rgba(255,255,255,0.6), -2px 0 6px rgba(0,0,0,0.15);
            border: 1px solid rgba(150,180,200,0.4);
            overflow: hidden;
        }

        .pipette-bulb::before {
            content: '';
            position: absolute;
            left: 4px;
            top: 6px;
            width: 4px;
            height: 60%;
            background: linear-gradient(180deg, rgba(255,255,255,0.8), rgba(255,255,255,0.4));
            border-radius: 2px;
            z-index: 2;
        }

        .pipette-bulb-liquid {
            position: absolute;
            bottom: 3px;
            left: 3px;
            right: 3px;
            height: 0%;
            background: transparent;
            border-radius: 50%;
            transition: height 0.8s ease-out, background 0.3s;
        }

        .pipette-tip {
            position: absolute;
            left: 50%;
            transform: translateX(-50%);
            background: linear-gradient(90deg,
                rgba(180,200,220,0.4),
                rgba(255,255,255,0.5) 30%,
                rgba(180,200,220,0.3) 70%,
                rgba(160,180,200,0.4)
            );
            border-radius: 0 0 2px 2px;
        }

        /* Beaker */
        .analyte-beaker {
            position: absolute;
            z-index: 10;
        }

        .beaker-body {
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            background: linear-gradient(90deg,
                rgba(200,220,240,0.25) 0%,
                rgba(255,255,255,0.5) 20%,
                rgba(200,220,240,0.15) 50%,
                rgba(180,200,220,0.35) 80%,
                rgba(160,180,200,0.25) 100%
            );
            border-radius: 0 0 6px 6px;
            box-shadow: inset -6px 0 15px rgba(255,255,255,0.6), -2px 2px 8px rgba(0,0,0,0.15);
            border: 1px solid rgba(150,180,200,0.4);
            border-top: none;
            overflow: hidden;
        }

        .beaker-body::before {
            content: '';
            position: absolute;
            left: 6px;
            top: 6px;
            width: 8px;
            height: 70%;
            background: linear-gradient(180deg, rgba(255,255,255,0.7), rgba(255,255,255,0.3));
            border-radius: 4px;
        }

        .beaker-spout {
            position: absolute;
            top: 0;
            right: -3px;
            background: linear-gradient(90deg, rgba(180,200,220,0.4), rgba(255,255,255,0.5) 50%, rgba(180,200,220,0.3));
            border-radius: 0 6px 0 0;
        }

        .beaker-liquid {
            position: absolute;
            bottom: 3px;
            left: 3px;
            right: 3px;
            background: transparent;
            border-radius: 0 0 5px 5px;
            transition: background 0.5s, height 0.5s;
        }

        .beaker-label {
            position: absolute;
            left: 50%;
            transform: translateX(-50%);
            font-weight: 600;
            color: #374151;
            white-space: nowrap;
        }

        /* Conical Flask */
        .conical-flask {
            position: absolute;
            z-index: 10;
        }

        .flask-neck {
            position: absolute;
            top: 0;
            left: 50%;
            transform: translateX(-50%);
            background: linear-gradient(90deg,
                rgba(200,220,240,0.3),
                rgba(255,255,255,0.6) 25%,
                rgba(200,220,240,0.2) 50%,
                rgba(180,200,220,0.4) 75%,
                rgba(160,180,200,0.3)
            );
            border-radius: 5px 5px 0 0;
            box-shadow: inset -3px 0 10px rgba(255,255,255,0.6);
            border: 1px solid rgba(150,180,200,0.4);
        }

        .flask-neck::before {
            content: '';
            position: absolute;
            left: 3px;
            top: 3px;
            width: 4px;
            height: 70%;
            background: linear-gradient(180deg, rgba(255,255,255,0.9), rgba(255,255,255,0.4));
            border-radius: 2px;
        }

        .flask-body {
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            background: linear-gradient(90deg,
                rgba(200,220,240,0.25),
                rgba(255,255,255,0.5) 20%,
                rgba(200,220,240,0.15) 50%,
                rgba(180,200,220,0.35) 80%,
                rgba(160,180,200,0.25)
            );
            border-radius: 0 0 50px 50px;
            box-shadow: inset -10px 0 20px rgba(255,255,255,0.6), -3px 3px 12px rgba(0,0,0,0.2);
            border: 1px solid rgba(150,180,200,0.4);
            overflow: hidden;
        }

        .flask-body::before {
            content: '';
            position: absolute;
            left: 10px;
            top: 6px;
            width: 12px;
            height: 80%;
            background: linear-gradient(180deg, rgba(255,255,255,0.7), rgba(255,255,255,0.3) 50%, rgba(255,255,255,0.5));
            border-radius: 50%;
            transform: skewY(-5deg);
        }

        .flask-liquid {
            position: absolute;
            bottom: 3px;
            left: 3px;
            right: 3px;
            background: transparent;
            border-radius: 0 0 45px 45px;
            transition: background-color 0.3s;
        }

        .feedback-popup {
            position: absolute;
            background: linear-gradient(135deg, #ffffff, #f8fafc);
            border-radius: 6px;
            padding: 8px 12px;
            box-shadow: 0 8px 30px rgba(0,0,0,0.15);
            font-size: 12px;
            z-index: 200;
            opacity: 0;
            transition: all 0.3s;
            border: 1px solid rgba(0,0,0,0.05);
        }

        .feedback-popup.show {
            opacity: 1;
            transform: translateY(-3px);
        }

        /* Procedure steps */
        #procedure-steps.procedure-steps-inline {
            display: flex;
            gap: 0.5rem;
            align-items: center;
            flex-wrap: nowrap;
            overflow-x: auto;
            padding: 0.25rem 0;
        }

        .procedure-step {
            white-space: nowrap;
            padding: 0.45rem 0.9rem;
            border-radius: 9999px;
            background: linear-gradient(135deg, #fef3c7, #fde68a);
            border: 1px solid #f59e0b;
            color: #92400e;
            font-weight: 600;
            font-size: 0.95rem;
            flex: 0 0 auto;
            box-shadow: 0 2px 8px rgba(245, 158, 11, 0.2);
            transition: all 0.2s;
            cursor: pointer;
        }

        .procedure-step:hover {
            transform: translateY(-2px);
        }

        .procedure-step.active {
            background: linear-gradient(135deg, #d1fae5, #a7f3d0);
            border-color: #059669;
            color: #065f46;
            box-shadow: 0 4px 15px rgba(5, 150, 105, 0.3);
        }

        .procedure-guide {
            background: linear-gradient(180deg, #ffffff, #f8fafc);
            border: 1px solid rgba(15, 23, 42, 0.08);
            padding: 1rem;
            border-radius: 12px;
            margin-top: 0.75rem;
            font-size: 0.95rem;
            color: #0f172a;
            box-shadow: 0 4px 20px rgba(0,0,0,0.05);
        }

        .guide-actions button {
            background: linear-gradient(135deg, #0ea5a4, #0d9488);
            color: white;
            padding: 0.35rem 0.6rem;
            border-radius: 8px;
            border: none;
            cursor: pointer;
            font-weight: 600;
            margin-right: 0.4rem;
            box-shadow: 0 4px 15px rgba(14, 165, 164, 0.3);
            transition: all 0.2s;
        }

        .glass-card {
            background: linear-gradient(135deg, rgba(255,255,255,0.95), rgba(248,250,252,0.95));
            border-radius: 16px;
            box-shadow: 0 10px 40px rgba(0,0,0,0.08);
            border: 1px solid rgba(0,0,0,0.05);
        }

        .control-btn {
            position: relative;
            overflow: hidden;
            transition: all 0.2s;
        }

        .control-btn:hover {
            transform: translateY(-2px);
        }

        select:focus, input:focus {
            outline: none;
            border-color: #0ea5a4;
            box-shadow: 0 0 0 3px rgba(14, 165, 164, 0.15);
        }

        .mode-btn {
            position: relative;
            overflow: hidden;
            transition: all 0.3s;
        }

        .mode-btn.active::after {
            content: '';
            position: absolute;
            bottom: 0;
            left: 50%;
            transform: translateX(-50%);
            width: 40%;
            height: 4px;
            background: linear-gradient(90deg, transparent, currentColor, transparent);
            border-radius: 4px;
        }

        .header-gradient {
            background: linear-gradient(135deg, #0d9488, #0284c7 50%, #0369a1);
            box-shadow: 0 10px 40px rgba(0,0,0,0.15);
        }

        /* Liquid colors */
        .analyte-naoh { background: linear-gradient(180deg, rgba(59,130,246,0.5), rgba(37,99,235,0.6)); }
        .analyte-koh { background: linear-gradient(180deg, rgba(16,185,129,0.5), rgba(5,150,105,0.6)); }
        .analyte-caoh2 { background: linear-gradient(180deg, rgba(6,182,212,0.5), rgba(8,145,178,0.6)); }

        /* Cortex AI Chat Button */
        #cortex-ai-chat-button {
            position: fixed;
            bottom: 20px;
            right: 20px;
            background: transparent;
            display: flex;
            align-items: center;
            justify-content: center;
            border: none;
            z-index: 1000;
            cursor: pointer;
        }

        #cortex-ai-chat-button img {
            width: 72px;
            height: 72px;
            box-shadow: 0 6px 24px rgba(0,0,0,0.25);
            border-radius: 18px;
            transition: transform 0.2s, box-shadow 0.2s;
        }

        #cortex-ai-chat-popup {
            position: fixed;
            bottom: 100px;
            right: 20px;
            width: 400px;
            height: 600px;
            border-radius: 16px;
            box-shadow: 0 10px 40px rgba(0,0,0,0.3);
            display: none;
            z-index: 1000;
            overflow: hidden;
        }

        /* ========================================
           DESKTOP DEFAULT SIZES
           ======================================== */

        /* Stand - Desktop */
        .burette-stand {
            left: 22%;
            top: 10px;
        }
        .stand-rod {
            width: 12px;
            height: 480px;
        }
        .stand-base {
            bottom: -15px;
            left: -30px;
            width: 80px;
            height: 25px;
        }
        .stand-clamp { width: 50px; height: 20px; left: 10px; }
        .clamp-top { top: 30px; }
        .clamp-bottom { top: 380px; }

        /* Burette - Desktop */
        .burette {
            width: 50px;
            height: 400px;
            left: 26%;
            top: 40px;
        }
        .burette-tip {
            bottom: -25px;
            width: 10px;
            height: 30px;
        }
        .reading-scale {
            right: -35px;
            top: 0;
            height: 100%;
            width: 30px;
            font-size: 10px;
            padding: 5px 2px;
        }
        .reading-scale div { font-size: 10px; }

        /* Pipette - Desktop */
        .pipette {
            width: 24px;
            height: 280px;
            left: 54%;
            top: 20px;
        }
        .pipette-body { height: 100%; }
        .pipette-bulb {
            top: 50px;
            width: 40px;
            height: 80px;
        }
        .pipette-tip {
            bottom: -18px;
            width: 6px;
            height: 22px;
        }

        /* Beaker - Desktop */
        .analyte-beaker {
            width: 100px;
            height: 120px;
            left: 52%;
            bottom: 90px;
        }
        .beaker-body { height: 100px; }
        .beaker-spout { width: 20px; height: 25px; }
        .beaker-liquid { height: 70px; }
        .beaker-label { bottom: -20px; font-size: 11px; }

        /* Conical Flask - Desktop */
        .conical-flask {
            width: 160px;
            height: 180px;
            left: 24%;
            bottom: 90px;
        }
        .flask-neck {
            width: 45px;
            height: 50px;
        }
        .flask-body { height: 140px; }
        .flask-liquid { height: 80px; }

        .working-area {
            position: absolute;
            right: 16px;
            top: 16px;
            width: 160px;
            padding: 12px;
            background: rgba(255,255,255,0.95);
            border-radius: 12px;
            box-shadow: 0 4px 15px rgba(0,0,0,0.1);
        }

        /* ========================================
           MOBILE RESPONSIVE STYLES
           ======================================== */
        @media (max-width: 768px) {
            body {
                padding: 4px;
                padding-bottom: 90px;
            }

            #canvas-wrapper {
                width: 100% !important;
                display: block !important;
            }

            #controls-sidebar {
                display: none !important;
            }

            .apparatus-container {
                min-height: 420px !important;
                height: 420px !important;
                width: 100% !important;
                display: block !important;
                visibility: visible !important;
                opacity: 1 !important;
            }

            .apparatus-container::before {
                height: 50px !important;
            }

            .working-area {
                display: none !important;
            }

            /* === MOBILE SIZES - No transforms, actual smaller sizes === */

            /* Stand - Mobile */
            .burette-stand {
                left: 5px !important;
                top: 5px !important;
            }
            .stand-rod {
                width: 5px !important;
                height: 180px !important;
            }
            .stand-base {
                bottom: -8px !important;
                left: -12px !important;
                width: 30px !important;
                height: 10px !important;
            }
            .stand-clamp { 
                width: 20px !important; 
                height: 8px !important; 
                left: 4px !important;
            }
            .clamp-top { top: 12px !important; }
            .clamp-bottom { top: 145px !important; }

            /* Burette - Mobile */
            .burette {
                width: 20px !important;
                height: 150px !important;
                left: 20px !important;
                top: 8px !important;
            }
            .burette-tip {
                bottom: -12px !important;
                width: 4px !important;
                height: 15px !important;
            }

            /* Reading Scale - Mobile (showing all values 0-50) */
            .reading-scale {
                display: flex !important;
                right: -22px !important;
                top: 0 !important;
                height: 150px !important;
                width: 18px !important;
                font-size: 6px !important;
                padding: 2px 1px !important;
            }
            .reading-scale div { 
                font-size: 6px !important; 
                line-height: 1;
            }

            /* Pipette - Mobile */
            .pipette {
                width: 10px !important;
                height: 105px !important;
                left: 65px !important;
                top: 8px !important;
            }
            .pipette-body { height: 100% !important; }
            .pipette-bulb {
                top: 18px !important;
                width: 16px !important;
                height: 32px !important;
            }
            .pipette-tip {
                bottom: -8px !important;
                width: 3px !important;
                height: 10px !important;
            }

            /* Beaker - Mobile */
            .analyte-beaker {
                width: 40px !important;
                height: 50px !important;
                left: 65px !important;
                top: 140px !important;
                bottom: auto !important;
            }
            .beaker-body { height: 40px !important; }
            .beaker-spout { width: 8px !important; height: 10px !important; }
            .beaker-liquid { height: 28px !important; }
            .beaker-label { bottom: -8px !important; font-size: 6px !important; }

            /* Conical Flask - Mobile */
            .conical-flask {
                width: 60px !important;
                height: 70px !important;
                left: 5px !important;
                top: 200px !important;
                bottom: auto !important;
            }
            .flask-neck {
                width: 18px !important;
                height: 20px !important;
            }
            .flask-body { height: 55px !important; }
            .flask-liquid { height: 35px !important; }

            /* Mobile bottom menu bar */
            .mobile-menu-bar {
                display: flex !important;
                position: fixed;
                bottom: 0;
                left: 0;
                right: 0;
                background: linear-gradient(180deg, #ffffff, #f8fafc);
                padding: 10px 16px;
                gap: 12px;
                justify-content: center;
                box-shadow: 0 -4px 20px rgba(0,0,0,0.15);
                z-index: 9999;
                border-top: 1px solid rgba(0,0,0,0.1);
            }

            .mobile-menu-btn {
                display: flex;
                flex-direction: column;
                align-items: center;
                justify-content: center;
                flex: 1;
                max-width: 100px;
                padding: 10px 8px;
                border-radius: 12px;
                border: none;
                cursor: pointer;
                color: white;
                font-size: 11px;
                font-weight: 600;
                box-shadow: 0 4px 15px rgba(0,0,0,0.2);
                transition: transform 0.2s;
            }

            .mobile-menu-btn:active {
                transform: scale(0.95);
            }

            .mobile-menu-btn svg {
                width: 24px;
                height: 24px;
                margin-bottom: 4px;
            }

            /* Mobile dropdown overlay */
            .mobile-dropdown-overlay {
                display: none;
                position: fixed;
                top: 0;
                left: 0;
                right: 0;
                bottom: 0;
                background: rgba(0,0,0,0.4);
                z-index: 10000;
            }

            .mobile-dropdown-overlay.show {
                display: block;
            }

            /* Mobile dropdown panels */
            .mobile-dropdown {
                display: none;
                position: fixed;
                bottom: 75px;
                left: 10px;
                right: 10px;
                background: white;
                border-radius: 16px;
                box-shadow: 0 10px 40px rgba(0,0,0,0.25);
                z-index: 10001;
                padding: 16px;
                max-height: 60vh;
                overflow-y: auto;
            }

            .mobile-dropdown.show {
                display: block;
            }

            .mobile-dropdown h4 {
                font-size: 16px;
                margin: 0 0 12px 0;
                padding-bottom: 8px;
                border-bottom: 2px solid #e5e7eb;
                color: #1f2937;
            }

            .mobile-dropdown label {
                display: block;
                font-size: 13px;
                margin-bottom: 4px;
                color: #4b5563;
            }

            .mobile-dropdown select {
                width: 100%;
                padding: 10px 12px;
                margin-bottom: 12px;
                border: 2px solid #e5e7eb;
                border-radius: 8px;
                font-size: 14px;
                background: white;
            }

            .mobile-dropdown .action-grid {
                display: grid;
                grid-template-columns: repeat(2, 1fr);
                gap: 8px;
            }

            .mobile-dropdown .action-btn {
                padding: 12px 8px;
                font-size: 12px;
                font-weight: 600;
                border: none;
                border-radius: 8px;
                cursor: pointer;
                color: white;
                text-align: center;
            }

            /* Compact procedure steps */
            #procedure-steps {
                flex-wrap: nowrap;
                overflow-x: auto;
                padding-bottom: 4px;
                gap: 4px;
            }

            .procedure-step {
                padding: 6px 10px;
                font-size: 11px;
                flex-shrink: 0;
            }

            #procedure-guide {
                display: block;
                padding: 8px;
                margin-top: 8px;
            }
            #procedure-guide h3 {
                display: none;
            }
            #procedure-guide-content {
                font-size: 12px;
            }
            .guide-actions {
                display: none;
            }

            h1 { font-size: 1.1rem !important; }
            .header-gradient { padding: 12px !important; }
            .header-gradient p { font-size: 12px !important; }
            .mode-btn { padding: 10px 16px !important; font-size: 13px !important; }
            .mode-btn .text-xs { display: none; }
        }

